    @EventHandler( payloadType=UpdateExperimentEvent.class )
    public void handle( UpdateExperimentEvent event) {
    	LOGGER.info("handling UpdateExperimentEvent - " + event );
    	
	    Experiment entity = new Experiment();
            entity.setExperimentId( event.getExperimentId() );
            entity.setName( event.getName() );
            entity.setObjective( event.getObjective() );
            entity.setWorkspace( event.getWorkspace() );
            entity.setTrainingRuns( event.getTrainingRuns() );
            entity.setModels( event.getModels() );
            entity.setNotebooks( event.getNotebooks() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindExperiment( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllExperiment( entity );        
    }
    
