    /**
     * Method to retrieve the Experiment via an ExperimentPrimaryKey.
     * @param 	id Long
     * @return 	Experiment
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Experiment handle( FindExperimentQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getExperimentId() );
    }
    
    /**
     * Method to retrieve a collection of all Experiments
     *
     * @param	query	FindAllExperimentQuery 
     * @return 	List<Experiment> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Experiment> handle( FindAllExperimentQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindExperiment,
 * but only if the id matches
 *
 * @param		entity	Experiment
 */
	protected void emitFindExperiment( Experiment entity ) {
		LOGGER.info("handling emitFindExperiment" );
		
	    queryUpdateEmitter.emit(FindExperimentQuery.class,
	                            query -> query.getFilter().getExperimentId().equals(entity.getExperimentId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllExperiment
	 * 
	 * @param		entity	Experiment
	 */
	protected void emitFindAllExperiment( Experiment entity ) {
		LOGGER.info("handling emitFindAllExperiment" );
		
	    queryUpdateEmitter.emit(FindAllExperimentQuery.class,
	                            query -> true,
	                            entity);
	}

